#pragma once
#include <juce_audio_utils/juce_audio_utils.h>
#include "Dsp.h"
using namespace juce;
inline const char* names[]{"LOW","BODY","PRESENCE","AIR","HIGH"};
inline const char* keys[]{"start","end","drive","output","threshold","ratio","knee","attack","release","range","mix","character","transient","sustain","colour","bypass","solo","cut","slope"};
inline const char* labels[]{"Start Hz","End Hz","Input / Drive dB","Output dB","Threshold dB","Ratio","Knee dB","Attack ms","Release ms","Max change dB","Wet / Dry","Velvet > Iron","Transient dB","Sustain dB","Colour (4x OS)","Bypass","Solo","Calibrated cut mix","Cut slope dB/oct"};
inline String id(int b,int p){return String(b)+"_"+keys[p];}
inline String rid(int r,const char* key){return "route"+String(r)+"_"+key;}
inline Colour colour(int b){static uint32 cs[]{0xff44d9c6,0xffffb455,0xffed709f,0xffa794ff,0xff62b9fb};return Colour(cs[b]);}
class Processor : public AudioProcessor {
public:
 AudioProcessorValueTreeState state;
 pong::Engine engine;
 std::array<std::array<std::atomic<float>*,pong::Count>,5> values{};
 std::array<std::atomic<float>*,pong::GCount> globals{};
 std::array<std::array<std::atomic<float>*,5>,pong::Routes> routeParams{};
 std::array<std::atomic<float>*,5> detectors{};
 std::array<std::atomic<float>,5> level{},gr{},adapt{},actualLo{},actualHi{},actualDrive{};
 std::array<std::atomic<float>,15> balls{};std::atomic<float> peak{0},limitGR{0},glueGR{0},hallMeter{0},wallLo{80},wallHi{16000};std::atomic<int> scoreL{0},scoreR{0};
 // Atomic snapshots with sequence counters. Readers retry; the audio writer never waits or locks.
 static constexpr int StateSize=272;
 std::array<std::atomic<double>,StateSize> snapshot{},pending{};std::atomic<unsigned> snapshotSeq{0},pendingSeq{0};unsigned consumed=0;
 std::atomic<float>* globalBypass=nullptr;bool forcedBypass=false,prepared=false;
 static AudioProcessorValueTreeState::ParameterLayout layout(){
  AudioProcessorValueTreeState::ParameterLayout l;constexpr float mins[]{20,20,-48,-48,-60,1,0,.05f,5,0,0,0,-48,-48,0,0,0,0,12};constexpr float maxs[]{20000,20000,48,48,0,30,24,200,2000,48,1,1,48,48,1,1,1,1,96};
  for(int b=0;b<5;++b)for(int j=0;j<pong::Count;++j){if(j==pong::Bypass||j==pong::Solo){l.add(std::make_unique<AudioParameterBool>(ParameterID{id(b,j),1},String(names[b])+" "+labels[j],false));continue;}NormalisableRange<float> r(mins[j],maxs[j]);if(j<2)r.setSkewForCentre(1000);if(j==7)r.setSkewForCentre(15);if(j==8)r.setSkewForCentre(160);if(j==pong::Slope){auto attributes=AudioParameterFloatAttributes().withStringFromValueFunction([](float v,int){return String(v<18?12:v<36?24:v<72?48:96);});l.add(std::make_unique<AudioParameterFloat>(ParameterID{id(b,j),1},String(names[b])+" "+labels[j],r,pong::defaults(b)[j],attributes));continue;}l.add(std::make_unique<AudioParameterFloat>(ParameterID{id(b,j),1},String(names[b])+" "+labels[j],r,pong::defaults(b)[j]));}
  l.add(std::make_unique<AudioParameterBool>(ParameterID{"lock",1},"Width Lock",true));l.add(std::make_unique<AudioParameterBool>(ParameterID{"global",1},"Global bypass",false));
  for(int j=0;j<pong::GCount;++j){auto s=pong::specs[j];if(j==pong::Play||j==pong::Sync||j==pong::Hold)l.add(std::make_unique<AudioParameterBool>(ParameterID{s.id,1},s.label,s.value>.5f));else if(j==pong::HallPos)l.add(std::make_unique<AudioParameterChoice>(ParameterID{s.id,1},s.label,StringArray{"PRE dynamics","POST insert","PARALLEL send"},2));else if(j==pong::Seed||j==pong::MidiCC)l.add(std::make_unique<AudioParameterInt>(ParameterID{s.id,1},s.label,int(s.min),int(s.max),int(s.value)));else l.add(std::make_unique<AudioParameterFloat>(ParameterID{s.id,1},s.label,NormalisableRange<float>{s.min,s.max},s.value));}
  for(int b=0;b<5;++b){StringArray options;for(auto n:pong::detectorNames)options.add(n);l.add(std::make_unique<AudioParameterChoice>(ParameterID{"detect"+String(b),1},String(names[b])+" Detector",options,0));}
  for(int r=0;r<pong::Routes;++r){StringArray sources,dests;for(auto n:pong::sourceNames)sources.add(n);for(auto n:pong::destinationNames)dests.add(n);l.add(std::make_unique<AudioParameterChoice>(ParameterID{rid(r,"src"),1},"Route "+String(r+1)+" source",sources,0));l.add(std::make_unique<AudioParameterChoice>(ParameterID{rid(r,"band"),1},"Route "+String(r+1)+" module",StringArray{"LOW","BODY","PRESENCE","AIR","HIGH"},1));l.add(std::make_unique<AudioParameterChoice>(ParameterID{rid(r,"dst"),1},"Route "+String(r+1)+" destination",dests,0));l.add(std::make_unique<AudioParameterFloat>(ParameterID{rid(r,"depth"),1},"Route "+String(r+1)+" signed depth",NormalisableRange<float>{-1,1},0));l.add(std::make_unique<AudioParameterFloat>(ParameterID{rid(r,"smooth"),1},"Route "+String(r+1)+" smoothing ms",NormalisableRange<float>{5,1000},50));}
  return l;
 }
 Processor():AudioProcessor(BusesProperties().withInput("Input",AudioChannelSet::stereo(),true).withInput("Sidechain",AudioChannelSet::stereo(),false).withOutput("Output",AudioChannelSet::stereo(),true)),state(*this,nullptr,"PONG_STAGE1",layout()){
  for(int b=0;b<5;++b){for(int j=0;j<pong::Count;++j)values[b][j]=state.getRawParameterValue(id(b,j));detectors[b]=state.getRawParameterValue("detect"+String(b));}for(int j=0;j<pong::GCount;++j)globals[j]=state.getRawParameterValue(pong::specs[j].id);for(int r=0;r<pong::Routes;++r){int k=0;for(auto s:{"src","band","dst","depth","smooth"})routeParams[r][k++]=state.getRawParameterValue(rid(r,s));}globalBypass=state.getRawParameterValue("global");publish();
 }
 void read(){for(int b=0;b<5;++b){for(int j=0;j<pong::Count;++j){float v=values[b][j]->load();engine.target[b][j]=std::isfinite(v)?v:pong::defaults(b)[j];}engine.detectorSource[b]=int(detectors[b]->load());}for(int j=0;j<pong::GCount;++j){float v=globals[j]->load();engine.global[j]=std::isfinite(v)?std::clamp(v,pong::specs[j].min,pong::specs[j].max):pong::specs[j].value;}for(int r=0;r<pong::Routes;++r)engine.routes[r]={int(routeParams[r][0]->load()),int(routeParams[r][1]->load()),int(routeParams[r][2]->load()),routeParams[r][3]->load(),routeParams[r][4]->load()};engine.globalTarget=forcedBypass?0:1-globalBypass->load();}
 void publish(){
  snapshotSeq.fetch_add(1);int n=0;for(auto& b:engine.motion.ball)for(float v:{b.x,b.y,b.vx,b.vy,b.pulse})snapshot[n++].store(v);snapshot[n++].store(engine.motion.rng);snapshot[n++].store(engine.motion.left);snapshot[n++].store(engine.motion.right);for(float v:engine.adaptive)snapshot[n++].store(v);for(float v:engine.routeValue)snapshot[n++].store(v);for(bool v:engine.motion.contact)snapshot[n++].store(v?1:0);snapshot[n++].store(engine.controlCounter);snapshot[n++].store(engine.filterCounter);for(bool v:engine.stress)snapshot[n++].store(v?1:0);for(float v:engine.sources)snapshot[n++].store(v);for(auto&route:engine.routeWeights)for(float v:route)snapshot[n++].store(v);snapshotSeq.fetch_add(1);
  for(int b=0;b<5;++b){level[b].store(engine.meter[b]);gr[b].store(engine.reduction[b]);adapt[b].store(24*engine.adaptive[b]*engine.gs[pong::Adapt]);actualLo[b].store(engine.effective[b][pong::Lo]);actualHi[b].store(engine.effective[b][pong::Hi]);actualDrive[b].store(engine.effective[b][pong::Drive]);}
  for(int b=0;b<3;++b){auto v=engine.motion.ball[b];balls[5*b].store(v.x);balls[5*b+1].store(v.y);balls[5*b+2].store(v.vx);balls[5*b+3].store(v.vy);balls[5*b+4].store(v.pulse);}peak.store(engine.outputPeak);limitGR.store(engine.limiter.reduction);glueGR.store(engine.glueReduction);hallMeter.store(engine.hallEnv);scoreL.store(engine.motion.left);scoreR.store(engine.motion.right);wallLo.store(engine.wallLo);wallHi.store(engine.wallHi);
 }
 void restorePending(){unsigned seq=pendingSeq.load();if(seq==consumed||seq&1)return;std::array<double,StateSize> a{};for(int n=0;n<StateSize;++n)a[n]=pending[n].load();if(seq!=pendingSeq.load())return;int n=0;for(auto&b:engine.motion.ball){b.x=float(a[n++]);b.y=float(a[n++]);b.vx=float(a[n++]);b.vy=float(a[n++]);b.pulse=float(a[n++]);}engine.motion.rng=std::uint32_t(a[n++]);engine.motion.left=int(a[n++]);engine.motion.right=int(a[n++]);for(auto&v:engine.adaptive)v=float(a[n++]);for(auto&v:engine.routeValue)v=float(a[n++]);for(auto&v:engine.motion.contact)v=a[n++]>.5;engine.controlCounter=int(a[n++])%32;engine.filterCounter=int(a[n++])%8;for(auto&v:engine.stress)v=a[n++]>.5;for(auto&v:engine.sources)v=float(a[n++]);for(auto&route:engine.routeWeights)for(auto&v:route)v=float(a[n++]);engine.lastSeed=unsigned(engine.global[pong::Seed]);consumed=seq;}
 const String getName()const override{return "PONG DYNAMICS";}bool acceptsMidi()const override{return true;}bool producesMidi()const override{return false;}double getTailLengthSeconds()const override{return 15;}
 int getNumPrograms()override{return 1;}int getCurrentProgram()override{return 0;}void setCurrentProgram(int)override{}const String getProgramName(int)override{return "Session";}void changeProgramName(int,const String&)override{}
 bool isBusesLayoutSupported(const BusesLayout& l)const override{bool main=l.getMainInputChannelSet()==l.getMainOutputChannelSet()&&(l.getMainOutputChannelSet()==AudioChannelSet::mono()||l.getMainOutputChannelSet()==AudioChannelSet::stereo());return main&&(l.inputBuses.size()<2||l.inputBuses[1].isDisabled()||l.inputBuses[1]==AudioChannelSet::mono()||l.inputBuses[1]==AudioChannelSet::stereo());}
 void prepareToPlay(double rate,int)override{auto savedMotion=engine.motion;int savedPhase=engine.controlCounter;unsigned previousSeed=engine.lastSeed;read();engine.prepare(float(rate));if(prepared&&previousSeed==unsigned(engine.global[pong::Seed])){engine.motion=savedMotion;engine.controlCounter=savedPhase;}prepared=true;restorePending();setLatencySamples(pong::Engine::Latency);publish();}
 void releaseResources()override{}
 void processBlock(AudioBuffer<float>& buffer,MidiBuffer& midi)override{ScopedNoDenormals no;read();restorePending();if(auto* playhead=getPlayHead())if(auto position=playhead->getPosition())if(auto bpm=position->getBpm())engine.tempo=float(std::clamp(*bpm,20.,400.));auto main=getBusBuffer(buffer,false,0);auto side=getBusBuffer(buffer,true,1);int channels=main.getNumChannels();auto it=midi.cbegin();
  for(int n=0;n<buffer.getNumSamples();++n){while(it!=midi.cend()&&(*it).samplePosition<=n){auto m=*it;if(m.numBytes>=3){int kind=m.data[0]&0xf0,number=m.data[1]&127;float value=(m.data[2]&127)/127.f;if(kind==0x90)engine.midi(1,number,value);else if(kind==0x80)engine.midi(0,number,0);else if(kind==0xb0)engine.midi(2,number,value);}++it;}std::array<float,2>x{};for(int c=0;c<channels;++c)x[c]=main.getSample(c,n);float sc=0;for(int c=0;c<side.getNumChannels();++c)sc=std::max(sc,std::abs(side.getSample(c,n)));auto y=engine.tick(x,channels,sc);for(int c=0;c<channels;++c)main.setSample(c,n,y[c]);}publish();
 }
 AudioProcessorParameter* getBypassParameter()const override{return state.getParameter("global");}void processBlockBypassed(AudioBuffer<float>& b,MidiBuffer&m)override{forcedBypass=true;processBlock(b,m);forcedBypass=false;}
 bool hasEditor()const override{return true;}AudioProcessorEditor* createEditor()override;
 void getStateInformation(MemoryBlock& out)override{auto tree=state.copyState();std::array<double,StateSize> a{};bool valid=false;for(int retry=0;retry<16&&!valid;++retry){unsigned s=snapshotSeq.load();if(s&1)continue;for(int n=0;n<StateSize;++n)a[n]=snapshot[n].load();valid=s==snapshotSeq.load();}if(valid){ValueTree motion("MotionV2");for(int n=0;n<StateSize;++n)motion.setProperty("v"+String(n),a[n],nullptr);tree.addChild(motion,-1,nullptr);}auto xml=tree.createXml();copyXmlToBinary(*xml,out);}
 void setStateInformation(const void* data,int size)override{auto xml=getXmlFromBinary(data,size);if(!xml||!xml->hasTagName(state.state.getType()))return;auto tree=ValueTree::fromXml(*xml);auto motion=tree.getChildWithName("MotionV2");if(motion.isValid()){pendingSeq.fetch_add(1);for(int n=0;n<StateSize;++n){double v=double(motion.getProperty("v"+String(n),0));pending[n].store(std::isfinite(v)?v:0);}pendingSeq.fetch_add(1);tree.removeChild(motion,nullptr);}state.replaceState(tree);}
};

